def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my_def = 0
    opp_def = 0
    for a, b in history:
        if a == 'D':
            my_def += 1
        if b == 'D':
            opp_def += 1

    if n >= 3 and opp_def >= n * 0.6:
        return 'D'

    if opp_def > n * 0.4:
        return 'D'

    last_my, last_opp = history[-1]

    if last_my == 'D' and last_opp == 'D':
        if opp_def < n * 0.4:
            return 'C'
        return 'D'

    if last_opp == 'D':
        if opp_def < n * 0.4:
            return 'C'
        return 'D'

    forgiveness_count = 0
    for i in range(n - 1):
        if history[i][0] == 'D' and history[i + 1][1] == 'C':
            forgiveness_count += 1

    recent_opp_def = 0
    for i in range(max(0, n - 5), n):
        if history[i][1] == 'D':
            recent_opp_def += 1

    if forgiveness_count > 0 and recent_opp_def == 0 and opp_def < n * 0.2:
        if forgiveness_count >= 8:
            return 'D'
        elif forgiveness_count >= 4:
            if n >= 3:
                all_c = True
                for i in range(1, 4):
                    if history[-i][0] != 'C':
                        all_c = False
                        break
                if all_c:
                    return 'D'
            return 'C'
        else:
            if n >= 6:
                all_c = True
                for i in range(1, 7):
                    if history[-i][0] != 'C':
                        all_c = False
                        break
                if all_c:
                    return 'D'
            return 'C'

    if my_def == 0 and opp_def == 0 and n >= 20 and n < 80:
        return 'D'

    return 'C'
